package pe.upn.yapaa_api.service;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.client.RestClient;import org.springframework.http.client.JdkClientHttpRequestFactory;
import pe.upn.yapaa_api.exception.*;import java.util.*;import java.time.*;import java.util.concurrent.ConcurrentHashMap;
@Service public class RutasService {
 public record Ruta(double distance,double duration){}public record Waypoint(double distance){}public record Respuesta(String code,List<Ruta> routes,List<Waypoint> waypoints){}
 private record Cache(double metros,long vence){}private final Map<String,Cache> cache=new ConcurrentHashMap<>();private final RestClient http;
 public RutasService(@Value("${yapaa.mapas.osrm:https://router.project-osrm.org}") String url){var f=new JdkClientHttpRequestFactory(java.net.http.HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build());f.setReadTimeout(Duration.ofSeconds(10));http=RestClient.builder().baseUrl(url).requestFactory(f).defaultHeader("User-Agent","YAPAA/1.0 (yapaaservice@gmail.com)").defaultHeader("Accept-Encoding","identity").defaultHeader("Accept-Encoding","identity").build();}
 public double distancia(double a,double b,double c,double d){CoberturaTrujillo.exigir(a,b);CoberturaTrujillo.exigir(c,d);String coordenadas=b+","+a+";"+d+","+c;var previa=cache.get(coordenadas);if(previa!=null&&previa.vence()>System.currentTimeMillis())return previa.metros();Respuesta r;
 try{r=http.get().uri("/route/v1/driving/"+coordenadas+"?overview=false&alternatives=false&steps=false&radiuses=250;250").retrieve().body(Respuesta.class);}catch(Exception e){org.slf4j.LoggerFactory.getLogger(RutasService.class).warn("Proveedor de rutas: {} / {}",e.getClass().getSimpleName(),e.getCause()==null?"sin causa":e.getCause().getClass().getSimpleName());throw new ServicioExternoException("No pudimos calcular la ruta. Reintenta o elige recojo.");}
 if(r==null||!"Ok".equals(r.code())||r.routes()==null||r.routes().isEmpty()||r.waypoints()==null||r.waypoints().size()!=2||r.waypoints().stream().anyMatch(p->p.distance()>250))throw new ReglaNegocioException("No hay una ruta de reparto para esa dirección.");double metros=r.routes().getFirst().distance();if(!Double.isFinite(metros)||metros<0)throw new ServicioExternoException("No se pudo calcular la distancia.");if(cache.size()>1000)cache.clear();cache.put(coordenadas,new Cache(metros,System.currentTimeMillis()+600000));return metros;}
}
